mapper.update:
UPDATE quota_definitions
SET quota_definition_status = 'ACTIVE',
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND quota_definition_status = 'DRAFT'

UPDATE plans
SET plan_status = 'ACTIVE',
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND plan_status = 'DRAFT'

mapper.select:
SELECT id
FROM quota_definitions
WHERE code = #{quotaCode}

SELECT pq.quota_limit
FROM subscriptions s
JOIN plan_quotas pq ON pq.plan_id = s.plan_id
WHERE s.tenant_id = #{tenantId}
  AND pq.quota_definition_id = #{quotaDefinitionId}

WITH adjusted AS (
    UPDATE quota_usages
    SET used = used + #{amount},
        updated_at = #{at}
    WHERE tenant_id = #{tenantId}
      AND quota_definition_id = #{quotaDefinitionId}
      AND used + #{amount} <= #{limit}
    RETURNING used
)
SELECT used FROM adjusted

WITH adjusted AS (
    UPDATE quota_usages
    SET used = used - #{amount},
        updated_at = #{at}
    WHERE tenant_id = #{tenantId}
      AND quota_definition_id = #{quotaDefinitionId}
      AND used >= #{amount}
    RETURNING used
)
SELECT used FROM adjusted

SELECT used
FROM quota_usages
WHERE tenant_id = #{tenantId}
  AND quota_definition_id = #{quotaDefinitionId}

mapper.delete:
DELETE FROM entitlement_bootstrap_idempotency
WHERE caller_identity_id = #{callerIdentityId}
  AND idempotency_key = #{idempotencyKey}
  AND expires_at <= #{now}

mapper.update:
UPDATE entitlement_bootstrap_idempotency
SET response_status = #{row.responseStatus},
    response_kind = #{row.responseKind},
    response_body = CAST(#{row.responseBody} AS JSONB),
    completed_at = #{row.completedAt}
WHERE caller_identity_id = #{row.callerIdentityId}
  AND idempotency_key = #{row.idempotencyKey}
  AND response_status IS NULL
